# -*- coding: utf-8 -*-
import argparse,base64,hashlib,io,os,tempfile,zipfile,runpy,sys
ARCHIVE_SHA256="4de7b25d52d9921bfa871b125077ac239ebc4c4fa449ac7694732ae56dab2ced"
ARCHIVE_B64=""""""
def main():
 p=argparse.ArgumentParser(description="Quantum Victory 1.3.0 — OFFLINE FILE FIRST")
 p.add_argument('--واجهة',action='store_true'); p.add_argument('--csv'); p.add_argument('--json'); p.add_argument('--server',action='store_true'); p.add_argument('--port',type=int,default=8501)
 args=p.parse_args()
 data=base64.b64decode(ARCHIVE_B64)
 if hashlib.sha256(data).hexdigest()!=ARCHIVE_SHA256: raise SystemExit('ARCHIVE_HASH_MISMATCH')
 td=tempfile.mkdtemp(prefix='qv130_')
 with zipfile.ZipFile(io.BytesIO(data)) as z: z.extractall(td)
 sys.path.insert(0,td)
 runpy.run_path(os.path.join(td,'Nafezu.py'),run_name='__main__')
if __name__=='__main__': main()
